sys_script_include.script:
var ToggleComplexProperty = Class.create();
ToggleComplexProperty.prototype = {
    initialize: function() {},

    toggleProperty: function() {
        var apiUrl = "/api/985627/sys_property_api/update-complex";
        var sysPropertyName = "sam.integration"; // Property name to update

        // Create REST Message
        var request = new sn_ws.RESTMessageV2();
        request.setEndpoint(apiUrl);
        request.setHttpMethod("POST");
        request.setRequestHeader("Content-Type", "application/json");
        request.setRequestBody(JSON.stringify({
            data: { name: sysPropertyName }
        }));

        // Execute API call
        var response = request.execute();
        var responseBody = response.getBody();
        var parsedResponse = JSON.parse(responseBody);

        return parsedResponse;
    }
};
;
